import express, { Express } from "express";
import { AddTaskUseCase } from "../application/AddTaskUseCase";
import { AssignTaskUseCase } from "../application/AssignTaskUseCase";
import { CreateProjectUseCase } from "../application/CreateProjectUseCase";
import { CreateUserUseCase } from "../application/CreateUserUseCase";
import { ListTasksUseCase } from "../application/ListTasksUseCase";
import { MarkTaskDoneUseCase } from "../application/MarkTaskDoneUseCase";
import { TaskFinderService } from "../application/TaskFinderService";
import { errorMiddleware } from "./errorMiddleware";
import { InMemoryProjectRepository } from "./InMemoryProjectRepository";
import { InMemoryTaskRepository } from "./InMemoryTaskRepository";
import { InMemoryUserRepository } from "./InMemoryUserRepository";
import { ProjectController } from "./ProjectController";
import { TaskController } from "./TaskController";
import { UserController } from "./UserController";
import { UuidIdGenerator } from "./UuidIdGenerator";

export function createApp(): Express {
  const projects = new InMemoryProjectRepository();
  const tasks = new InMemoryTaskRepository();
  const users = new InMemoryUserRepository();
  const ids = new UuidIdGenerator();
  const finder = new TaskFinderService(tasks);

  const userController = new UserController(
    new CreateUserUseCase(users, ids),
  );
  const projectController = new ProjectController(
    new CreateProjectUseCase(projects, ids),
  );
  const taskController = new TaskController({
    addTask: new AddTaskUseCase(projects, tasks, ids),
    assignTask: new AssignTaskUseCase(finder, tasks, users),
    listTasks: new ListTasksUseCase(projects, tasks),
    markTaskDone: new MarkTaskDoneUseCase(finder, tasks),
  });

  const app = express();
  app.use(express.json());
  app.use(userController.routes());
  app.use(projectController.routes());
  app.use(taskController.routes());
  app.use(errorMiddleware);
  return app;
}

